alter table private.player_immortal_states add column if not exists guide_job_target integer check(guide_job_target between 1 and 3),add column if not exists guide_job_started_at timestamptz,add column if not exists guide_job_completes_at timestamptz,add column if not exists outpost_job_target integer check(outpost_job_target between 1 and 3),add column if not exists outpost_job_started_at timestamptz,add column if not exists outpost_job_completes_at timestamptz;

create or replace function private.immortal_snapshot(s private.player_immortal_states)returns jsonb language sql stable set search_path='' as $$select jsonb_build_object('revision',s.revision,'residualSource',s.residual_source,'barrenTraces',s.barren_traces,'timelineStartedAt',floor(extract(epoch from s.timeline_started_at)*1000),'region',s.region,'investigated',s.investigated,'firstBattleWon',s.first_battle_won,'guideStoneStage',s.guide_stone_stage,'restorationJob',case when s.guide_job_target is null then null else jsonb_build_object('targetStage',s.guide_job_target,'startedAt',floor(extract(epoch from s.guide_job_started_at)*1000),'completesAt',floor(extract(epoch from s.guide_job_completes_at)*1000))end,'expeditionUnlocked',s.expedition_unlocked,'expedition',jsonb_build_object('active',s.expedition_active,'node',s.expedition_node,'runs',s.expedition_runs),'outerRouteCleared',s.outer_route_cleared,'expeditionDaily',jsonb_build_object('date',private.immortal_day()::text,'used',case when s.expedition_day=private.immortal_day()then s.expedition_used else 0 end),'storyFlags',s.story_flags,'platformChapterCompleted',s.platform_chapter_completed,'wasteland',jsonb_build_object('arrivalSeen',s.wasteland_arrival_seen,'selectedRoute',s.wasteland_selected_route,'routeProgress',s.wasteland_route_progress,'outpostStage',s.wasteland_outpost_stage,'outpostJob',case when s.outpost_job_target is null then null else jsonb_build_object('targetStage',s.outpost_job_target,'startedAt',floor(extract(epoch from s.outpost_job_started_at)*1000),'completesAt',floor(extract(epoch from s.outpost_job_completes_at)*1000))end,'bodyStage',s.wasteland_body_stage,'storyFlags',s.wasteland_story_flags))$$;

create or replace function public.player_immortal_restoration_command(p_channel text,p_kind text,p_action text,p_request_id uuid)returns jsonb language plpgsql security definer set search_path='' as $$
declare uid uuid:=(select auth.uid());s private.player_immortal_states;a private.player_ascension_states;w private.player_resource_wallets;stage integer;target integer;source_cost integer:=0;trace_cost integer:=0;wood_cost integer:=0;iron_cost integer:=0;duration interval;
begin if uid is null then raise exception '需要重新登入';end if;if p_channel not in('formal','test')or p_kind not in('guide','outpost')or p_action not in('start','claim')or p_request_id is null then raise exception '復界工程請求不正確';end if;if exists(select 1 from private.player_state_events where user_id=uid and channel=p_channel and request_id=p_request_id)then raise exception '重複的復界工程請求';end if;perform pg_advisory_xact_lock(hashtext(uid::text||'-immortal-job-'||p_channel));select * into s from private.player_immortal_states where user_id=uid and channel=p_channel for update;select * into a from private.player_ascension_states where user_id=uid and channel=p_channel;select * into w from private.player_resource_wallets where user_id=uid and channel=p_channel for update;if s.user_id is null or not a.ascended then raise exception '尚未踏入仙界';end if;if w.user_id is null then raise exception '伺服器資源帳本尚未建立';end if;
if p_kind='guide'then stage:=s.guide_stone_stage;if p_action='start'then if stage>=3 then raise exception '引道碑已完成';end if;if s.guide_job_target is not null then raise exception '目前已有復界工程進行中';end if;target:=stage+1;source_cost:=case stage when 0 then 2 when 2 then 4 else 0 end;trace_cost:=case stage when 1 then 1 when 2 then 2 else 0 end;iron_cost:=case when stage=1 then 300 else 0 end;wood_cost:=case when stage=2 then 500 else 0 end;duration:=case stage when 0 then interval'4 hours'when 1 then interval'20 hours'else interval'48 hours'end;if s.residual_source<source_cost or s.barren_traces<trace_cost or w.meteor_iron<iron_cost or w.wood<wood_cost then raise exception '引道碑工程材料不足';end if;update private.player_immortal_states set residual_source=residual_source-source_cost,barren_traces=barren_traces-trace_cost,guide_job_target=target,guide_job_started_at=now(),guide_job_completes_at=now()+duration,revision=revision+1,updated_at=now()where user_id=uid and channel=p_channel returning * into s;if wood_cost+iron_cost>0 then update private.player_resource_wallets set wood=wood-wood_cost,meteor_iron=meteor_iron-iron_cost,revision=revision+1,updated_at=now()where user_id=uid and channel=p_channel returning * into w;end if;else if s.guide_job_target is null then raise exception '目前沒有可領取的引道碑工程';end if;if now()<s.guide_job_completes_at then raise exception '引道碑工程尚未完成';end if;target:=s.guide_job_target;update private.player_immortal_states set guide_stone_stage=target,guide_job_target=null,guide_job_started_at=null,guide_job_completes_at=null,revision=revision+1,updated_at=now()where user_id=uid and channel=p_channel returning * into s;end if;
else stage:=s.wasteland_outpost_stage;if s.guide_stone_stage<3 or not s.outer_route_cleared or coalesce((s.wasteland_route_progress->>'dryWind')::integer,0)<3 then raise exception '荒原據點尚未解鎖';end if;if p_action='start'then if stage>=3 then raise exception '荒原據點已完成';end if;if s.outpost_job_target is not null then raise exception '目前已有荒原據點工程';end if;target:=stage+1;source_cost:=(array[5,9,15])[target];trace_cost:=(array[2,4,7])[target];duration:=(array[interval'8 hours',interval'24 hours',interval'72 hours'])[target];if s.residual_source<source_cost or s.barren_traces<trace_cost then raise exception '荒原據點材料不足';end if;update private.player_immortal_states set residual_source=residual_source-source_cost,barren_traces=barren_traces-trace_cost,outpost_job_target=target,outpost_job_started_at=now(),outpost_job_completes_at=now()+duration,revision=revision+1,updated_at=now()where user_id=uid and channel=p_channel returning * into s;else if s.outpost_job_target is null then raise exception '目前沒有可領取的荒原據點工程';end if;if now()<s.outpost_job_completes_at then raise exception '荒原據點工程尚未完成';end if;target:=s.outpost_job_target;update private.player_immortal_states set wasteland_outpost_stage=target,outpost_job_target=null,outpost_job_started_at=null,outpost_job_completes_at=null,revision=revision+1,updated_at=now()where user_id=uid and channel=p_channel returning * into s;end if;end if;
insert into private.player_state_events(user_id,channel,revision,event_type,request_id,payload)values(uid,p_channel,s.revision,'immortal_'||p_kind||'_'||p_action,p_request_id,jsonb_build_object('targetStage',target));return jsonb_build_object('immortal',private.immortal_snapshot(s),'wallet',private.wallet_snapshot(w));end$$;

revoke execute on function public.player_immortal_restoration_command(text,text,text,uuid)from public,anon;grant execute on function public.player_immortal_restoration_command(text,text,text,uuid)to authenticated;
